#include <iostream>
#include <string>
#include <stdexcept>

struct Tracker {
    std::string name;
    Tracker(std::string n) : name(std::move(n)) {
        std::cout << "Constructed: " << name << "\n";
    }
    ~Tracker() {
        std::cout << "Destructed: " << name << "\n";
    }
};

struct Composite {
    Tracker m1;
    Tracker m2;
    Composite() : m1("Member1"), m2("Member2") {
        std::cout << "Composite constructor throwing error\n";
        throw std::runtime_error("Initialization failed inside Composite");
    }
    ~Composite() {
        std::cout << "Composite destructor (never called)\n";
    }
};

void deepNested() {
    Tracker local("LocalInDeepNested");
    Composite comp;
}

int main() {
    try {
        deepNested();
    } catch (const std::exception& e) {
        std::cout << "Caught in main: " << e.what() << "\n";
    }
    return 0;
}

#include <iostream>
#include <stdexcept>

class CustomError : public std::runtime_error {
public:
    CustomError(const std::string& msg) : std::runtime_error(msg) {}
};

void testTernaryThrow(bool flag) {
    try {
        // Ternary operator type resolves statically to double
        throw (flag ? 100 : 3.14);
    } catch (int) {
        std::cout << "Caught int\n";
    } catch (double d) {
        std::cout << "Caught double: " << d << "\n";
    }
}

void handleAndRethrow() {
    try {
        throw CustomError("Original specialized failure");
    } catch (const CustomError& e) {
        std::cout << "Intermediate catch: logging and rethrowing\n";
        throw; // Rethrowing does not cause infinite recursion
    }
}

int main() {
    // 1. Ternary throw demonstration
    testTernaryThrow(true);

    // 2. Hierarchical catch and rethrow
    try {
        handleAndRethrow();
    } catch (const std::runtime_error& e) {
        std::cout << "Outer catch (base class): " << e.what() << "\n";
    }
    return 0;
}
